import copy
import json
from pathlib import Path

import httpx
import pytest

from odingard_guardian import (
    fetch_receipt_verification_keys,
    verify_receipt_offline,
    verify_receipt_online,
)

CASES = json.loads((Path(__file__).parent / "fixtures" / "receipts.json").read_text("utf-8"))


@pytest.mark.parametrize("case", CASES, ids=lambda c: c["name"])
def test_parity_with_typescript_verifier(case):
    """Golden fixtures generated by scripts/gen-fixtures.ts from the TypeScript SDK."""
    got = verify_receipt_offline(case["receipt"], case["keys"])
    expected = case["expected"]
    assert got["valid"] == expected["valid"]
    if expected["valid"]:
        assert got["decision"] == expected["decision"]
        assert got["effect"] == expected["effect"]
        assert got["subject"] == expected["subject"]
    else:
        assert got["reasonCode"] == expected["reasonCode"]


def _valid():
    case = next(c for c in CASES if c["name"] == "valid")
    return copy.deepcopy(case["receipt"]), case["keys"]


def test_every_single_field_edit_is_detected():
    receipt, keys = _valid()
    assert verify_receipt_offline(receipt, keys)["valid"] is True
    for path in (("action", "purpose"), ("decision", "decidedAtEpochMs"), ("subject", "agentId"), ("receiptId",)):
        tampered = copy.deepcopy(receipt)
        target = tampered
        for key in path[:-1]:
            target = target[key]
        value = target[path[-1]]
        target[path[-1]] = value + 1 if isinstance(value, int) else value + "x"
        assert verify_receipt_offline(tampered, keys)["valid"] is False, path


def test_malformed_keys_fail_closed():
    receipt, _ = _valid()
    assert verify_receipt_offline(receipt, {"keys": []}) == {"valid": False, "reasonCode": "MALFORMED_RECEIPT"}
    assert verify_receipt_offline(receipt, None)["valid"] is False


def test_fetch_keys_and_online_verify():
    _, keys = _valid()

    def handler(request: httpx.Request) -> httpx.Response:
        if request.url.path == "/v1/receipts/verification-keys":
            return httpx.Response(200, json=keys)
        if request.url.path == "/v1/receipts/verify":
            return httpx.Response(200, json={"valid": True})
        return httpx.Response(404)

    transport = httpx.MockTransport(handler)
    assert fetch_receipt_verification_keys("https://g.test/", transport=transport) == {"ok": True, "keys": keys}
    assert verify_receipt_online("https://g.test", {}, transport=transport) == {"ok": True, "result": {"valid": True}}


def test_fetch_keys_unreachable_is_a_refusal():
    def handler(request: httpx.Request) -> httpx.Response:
        raise httpx.ConnectError("down", request=request)

    result = fetch_receipt_verification_keys("https://g.test", transport=httpx.MockTransport(handler))
    assert result == {"ok": False, "reasonCode": "SERVICE_UNAVAILABLE"}


def test_verify_accepts_the_fetch_result_as_returned():
    receipt, keys = _valid()

    def handler(request: httpx.Request) -> httpx.Response:
        return httpx.Response(200, json=keys)

    fetched = fetch_receipt_verification_keys("https://g.test", transport=httpx.MockTransport(handler))
    assert verify_receipt_offline(receipt, fetched)["valid"] is True
    assert verify_receipt_offline(receipt, fetched["keys"])["valid"] is True
    assert verify_receipt_offline(receipt, {"ok": False, "reasonCode": "HTTP_503"})["valid"] is False
    assert verify_receipt_offline(receipt, {"ok": True})["valid"] is False


def test_key_fetch_can_ask_for_an_older_receipts_signing_key():
    urls = []

    def handler(request):
        urls.append(str(request.url))
        return httpx.Response(200, json={"keys": []})

    transport = httpx.MockTransport(handler)
    fetch_receipt_verification_keys("https://guardian.test/", transport=transport)
    fetch_receipt_verification_keys(
        "https://guardian.test", for_receipt={"proof": {"keyId": "rkey_abc123"}}, transport=transport
    )
    fetch_receipt_verification_keys("https://guardian.test", kid="rkey_def456", transport=transport)
    fetch_receipt_verification_keys(
        "https://guardian.test", for_receipt={"proof": {"keyId": "rkey_x&evil=1"}}, transport=transport
    )
    assert urls == [
        "https://guardian.test/v1/receipts/verification-keys",
        "https://guardian.test/v1/receipts/verification-keys?kid=rkey_abc123",
        "https://guardian.test/v1/receipts/verification-keys?kid=rkey_def456",
        "https://guardian.test/v1/receipts/verification-keys",
    ]
